  const QUICK_MODE_KEY = 'aed:quick-mode';
  const ADDONS_PENDING_KEY = 'aed:addons-pending';
  const IMAGE_LIBRARY_KEY = 'aed:image-library';
  const ADDONS_SORT_KEY = 'aed:addons-sort';
  const ADDONS_FILTER_KEY = 'aed:addons-filter';
  const ADDONS_FILTER_VALUES = ['enabled', 'all'];
  // Sitemap expand/collapse state — set of top-segment keys that are open
  // right now. Default is "all collapsed except the current page's group"
