      // and are applied to the correct Nth-of-type section by Base.astro's head script.
      const secIndex = typeCounts[typeKey] || 0;
      typeCounts[typeKey] = secIndex + 1;

      const frame = document.createElement('div');
      frame.className = 'aed-sec-frame';

      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'aed-sec-chip';
      chip.innerHTML = `${PALETTE_SVG}<span class="aed-sec-chip-label"></span><span class="aed-sec-chip-variant"></span>`;
      const labelEl = chip.querySelector('.aed-sec-chip-label');
      const variantEl = chip.querySelector('.aed-sec-chip-variant');
      labelEl.textContent = label;

